def compute(vars):
    total_expense = vars["v2"]
    if total_expense == 0:
        return None

    proportion = vars["v1"] / total_expense
    percentage = proportion * 100

    return {
        "value": percentage,
        "trace": {
            "proportion": proportion,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
